import pytest
from queue import Full, Queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts.

    Creates a queue holding at most cap integers, then tries to put each
    element of xs in order without blocking. Stops at the first put that
    finds the queue full and returns the number of puts accepted before
    that. A capacity of zero or less accepts nothing.
    """
    if cap <= 0:
        # Queue treats maxsize <= 0 as unbounded, so handle it explicitly.
        return 0
    q: Queue[int] = Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_accepted_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_accepted_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(5, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_negative_capacity() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_accepted_single_slot() -> None:
    assert accepted(1, [4, 4, 4]) == 1


def test_accepted_duplicates_are_counted() -> None:
    assert accepted(4, [2, 2, 2, 2, 2, 2]) == 4


@pytest.mark.parametrize(
    ("cap", "n", "expected"),
    [(0, 5, 0), (1, 5, 1), (5, 5, 5), (6, 5, 5), (2, 0, 0)],
)
def test_accepted_parametrized(cap: int, n: int, expected: int) -> None:
    assert accepted(cap, list(range(n))) == expected
